import 'dart:async'; import 'package:flutter/material.dart'; import '../../core/theme/app_colors.dart'; import '../../core/widgets/ui.dart'; import '../../state/app_state.dart'; import '../shell.dart';
class FlowScreen extends StatefulWidget{const FlowScreen({super.key});@override State<FlowScreen> createState()=>_FlowScreenState();}
class _FlowScreenState extends State<FlowScreen>{int page=-1;bool signup=false;int ob=0;final name=TextEditingController(),id=TextEditingController(),pw=TextEditingController();String? error;
@override void initState(){super.initState();Timer(const Duration(milliseconds:2200),(){if(mounted)setState(()=>page=AppScope.of(context).onboardingDone?1:0);});}
@override Widget build(BuildContext c){if(page==-1)return Scaffold(body:Container(decoration:const BoxDecoration(gradient:LinearGradient(colors:[AppColors.green,AppColors.greenDark],begin:Alignment.topRight,end:Alignment.bottomLeft)),child:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:112,height:112,decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(34)),alignment:Alignment.center,child:const Text('🕋',style:TextStyle(fontSize:54))),const SizedBox(height:14),const Text('رفيق المعتمر',style:TextStyle(color:Colors.white,fontSize:38,fontWeight:FontWeight.w800)),const Text('معك من النية إلى التحلل',style:TextStyle(color:Colors.white70))]))));
if(page==0){const data=[('🕋','عمرتك خطوة بخطوة','دليل تفاعلي بالأدعية ومحاكاة للطواف والسعي، وعدّاد يحفظ تقدمك.'),('🗺️','خريطة الحرم وزر «أنا تائه»','اعرف أقرب باب وطريقك، وأبلغ مجموعتك بمكانك بضغطة واحدة.'),('👥','رفاقك ومنبهك','اجمع أهلك بكود واحد، وصحّيك بصوتك ورسالتك للفجر والطواف.')];final s=data[ob];return Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Align(alignment:Alignment.centerLeft,child:TextButton(onPressed:()=>setState(()=>page=1),child:const Text('تخطّي'))),const Spacer(),Container(width:300,height:300,decoration:BoxDecoration(gradient:const LinearGradient(colors:[AppColors.green,AppColors.greenDark]),borderRadius:BorderRadius.circular(36)),alignment:Alignment.center,child:Text(s.$1,style:const TextStyle(fontSize:104))),const SizedBox(height:20),Text(s.$2,style:const TextStyle(fontSize:25,fontWeight:FontWeight.w800)),Text(s.$3,textAlign:TextAlign.center),const Spacer(),PrimaryButton(ob==2?'ابدأ الآن':'التالي',onTap:(){if(ob==2){final st=AppScope.of(c);st.change(()=>st.onboardingDone=true);setState(()=>page=1);}else setState(()=>ob++);})]))));}
return Scaffold(body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[Container(width:72,height:72,decoration:BoxDecoration(color:AppColors.green,borderRadius:BorderRadius.circular(22)),alignment:Alignment.center,child:const Text('🕋',style:TextStyle(fontSize:34))),const SizedBox(height:12),Text(signup?'أنشئ حسابك':'أهلًا بعودتك',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:16),SegButton(signup:signup,onChanged:(v)=>setState(()=>signup=v)),AppCard(child:Column(children:[if(signup)...[TextField(controller:name,decoration:const InputDecoration(labelText:'الاسم')),const SizedBox(height:8)],TextField(controller:id,textDirection:TextDirection.ltr,decoration:const InputDecoration(labelText:'رقم الجوال أو البريد')),const SizedBox(height:8),TextField(controller:pw,obscureText:true,textDirection:TextDirection.ltr,decoration:const InputDecoration(labelText:'كلمة المرور')),if(error!=null)Align(alignment:Alignment.centerRight,child:Text(error!,style:const TextStyle(color:AppColors.red))),const SizedBox(height:8),PrimaryButton(signup?'إنشاء الحساب':'دخول',onTap:()=>login(c)),const SizedBox(height:12),const Text('أو'),const SizedBox(height:8),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>go(c),child:const Text('Apple'))),const SizedBox(width:8),Expanded(child:OutlinedButton(onPressed:()=>go(c),child:const Text('G Google')))])])),const SizedBox(height:12),PrimaryButton('متابعة كضيف',outline:true,onTap:()=>go(c))]))));}
void login(BuildContext c){if(signup&&name.text.trim().length<2){setState(()=>error='اكتب اسمك');return;}if(id.text.trim().length<6){setState(()=>error='أدخل جوالًا أو بريدًا صحيحًا');return;}if(pw.text.length<6){setState(()=>error='كلمة المرور 6 أحرف على الأقل');return;}final st=AppScope.of(c);st.change((){st.loggedIn=true;if(name.text.isNotEmpty)st.name=name.text;});go(c);}void go(BuildContext c){AppScope.of(c).change(()=>AppScope.of(c).loggedIn=true);Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const AppShell()));}}
class SegButton extends StatelessWidget{final bool signup;final ValueChanged<bool> onChanged;const SegButton({super.key,required this.signup,required this.onChanged});@override Widget build(BuildContext c)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(4),decoration:BoxDecoration(color:AppColors.line,borderRadius:BorderRadius.circular(14)),child:Row(children:[for(final x in [(false,'تسجيل الدخول'),(true,'حساب جديد')])Expanded(child:TextButton(style:TextButton.styleFrom(backgroundColor:signup==x.$1?Theme.of(c).cardColor:null),onPressed:()=>onChanged(x.$1),child:Text(x.$2)))]));}
